mapper.select:
select dt.id, dt.file_id, df.file_name, dt.type, dt.status, dt.last_error, dt.created_at from `document_task` dt left join `document_file` df on dt.file_id = df.id left join `knowledge_base_document` kdb on dt.file_id = kdb.file_id where kdb.knowledge_base_id = #{knowledgeBaseId}
and dt.status = #{status}
order by dt.created_at desc
